package main

import (
	"bufio"
	"fmt"
	"os"
	"sort"
)

func POWER(base, expo int64) int64 {
	var num int64 = 1
	for i := expo; i > 0; i-- {
		num *= base
	}
	return num
}

func main() {
	in := bufio.NewReader(os.Stdin)
	out := bufio.NewWriter(os.Stdout)
	defer out.Flush()

	var t int64 = 1
	for t > 0 {
		t--

		var n, m, k int64
		fmt.Fscan(in, &n, &m, &k)

		a := make([]int64, int(n))
		for i := int64(0); i < n; i++ {
			fmt.Fscan(in, &a[int(i)])
		}

		sort.Slice(a, func(i, j int) bool {
			return a[i] < a[j]
		})

		if m <= k {
			fmt.Fprint(out, 0)
		} else {
			var sum int64
			i := n
			devices := m
			soc := k

			for sum < m && devices > soc && i >= 1 {
				i--
				sum += a[int(i)]
				devices -= a[int(i)]
				soc--
			}

			if devices <= soc {
				fmt.Fprint(out, n-i)
			} else {
				i = n
				var used, ss, j int64

				for i >= 1 && ss < m {
					i--
					if used >= k*j && j >= 1 {
						ss--
					}
					ss += a[int(i)]
					used++
					if used%k == 0 && used != 0 {
						j++
					}
				}

				if ss >= m {
					fmt.Fprint(out, used)
				} else {
					fmt.Fprint(out, -1)
				}
			}
		}
	}
}

